SELECT sku, gtin, product_name, pack_size, case_units, flow, case_kg
FROM store.products
WHERE pack_size LIKE '%5 kg%' OR product_name ILIKE '%atta%' OR product_name ILIKE '%attha%';

SELECT sku, name, pack, flow, case_units, case_kg
FROM store.products
WHERE pack LIKE '%5 kg%' OR name ILIKE '%atta%';

SELECT sku, gtin, name, pack, case_units, case_kg, flow
FROM store.products
WHERE sku = 'ATTA-WW-5KG';
